{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Background: There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement.",
      "reason": "The manuscript explicitly states the current state of knowledge (limited evidence) about evaluating sustainability of EBIs, establishing an important uncertainty the review addresses."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Discussion: It is unclear which approach/approaches are most effective for evaluating sustainability and what measures and outcomes are most commonly used. There is a disconnect between evaluating the factors that may shape sustainability and the outcomes approaches employed to measure sustainability. Our review offers methodological recommendations for sustainability evaluation research and highlights the importance in understanding mechanisms of sustainability to advance the field.",
      "reason": "The manuscript explains the need and importance of the review by identifying gaps (uncertainty about effective approaches and measures) and stating that the review will provide methodological recommendations to advance the field."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research.",
      "reason": "The authors compare their review to existing syntheses and state how the current review differs, indicating awareness of prior reviews and justifying the need for this review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review addresses approaches to evaluating sustainability of EBIs rather than assessing intervention effects; thus describing a mechanism of action for an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence in the provided text indicates the inclusion or presentation of a logic model to show hypothesised relationships between intervention components and outcomes."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "The aim of this integrative review was to identify and synthesize approaches that have been used to evaluate the sustainability of EBIs in healthcare. We aimed to enhance our understanding of sustainability definitions, research designs, data collection methods, timing, measures, and sustainability outcomes used for sustainability evaluation studies.",
      "reason": "The manuscript explicitly states clear aims and several specific objectives (identify and synthesize approaches; enhance understanding of definitions, designs, methods, timing, measures, outcomes). However, these objectives are not presented using a recognized question-formulation framework (e.g., PICO or similar), so the requirement to use a relevant question-formulation framework is not met."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_6",
      "quote": "The aim of this integrative review was to identify and synthesize approaches that have been used to evaluate the sustainability of EBIs in healthcare. We aimed to enhance our understanding of sustainability definitions, research designs, data collection methods, timing, measures, and sustainability outcomes used for sustainability evaluation studies.",
      "reason": "The review is an integrative review focused on approaches to evaluate sustainability of EBIs, not a review of intervention effects or planned comparisons. Therefore specifying planned comparisons using PICO is not applicable."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "table_0",
      "quote": "Articles were included if they: • Were published in a peer-review journal • Were primary research • Had explicit research design and data collection methods • Had an explicit theoretical ­ approach a for sustainability ­ (theory b , ­ model c , ­ framework d , ­ instrument e , method, checklist, process, strategy, conceptual- izations, development, pilot test and/or ­ tool f ) • Were within a healthcare ­ setting g • Evaluated the sustainability of an EBI (Note that inconsistent terminology for EBI is prominent and thus may be referred to as a QI intervention/ initia- tive in the literature).",
      "reason": "Table 1 explicitly lists study characteristics used to determine eligibility including study design, theoretical approach, healthcare setting, and requirement to evaluate sustainability of an EBI."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_21",
      "quote": "We only included published studies in the English language and peer-reviewed primary studies in this review. This review entailed a comprehensive search of published literature and rigorous review methods; however, we recognize that there is the possibility of incomplete retrieval of identified research. For example, all gray literature was excluded.",
      "reason": "The manuscript states report-level eligibility restrictions (published, peer-reviewed, English language) and notes exclusion of gray literature."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement distinguishing exclusion because outcomes were not measured versus exclusion because outcome results were not reported is present in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found specifying groups used in each synthesis or linking groups to comparisons defined in the review objectives in the provided material."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_21",
      "quote": "We only included published studies in the English language and peer-reviewed primary studies in this review. ... For example, all gray literature was excluded.",
      "reason": "The authors state notable restrictions (English language, peer-reviewed, exclusion of gray literature) and acknowledge potential incomplete retrieval, but do not provide detailed rationales or justification for these restrictions beyond acknowledgement."
    }
  ],
  "confidence": 80
}

